{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, a chlorinated sulfamoyl diuretic structurally related to the query, is approximately 100% bioavailable in humans after oral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hydrochlorothiazide, which shares the sulfamoyl chlorophenyl diuretic motif, has an absolute oral bioavailability of 66–75% in healthy adults.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Bumetanide, another sulfamoyl-containing diuretic, shows oral bioavailability around 66% or higher in healthy subjects, supporting good oral absorption for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a less similar sulfamoyl diuretic, has low oral bioavailability of 10–19% in humans, but this is attributed to high first-pass metabolism and is outweighed by the higher-similarity analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a chlorthalidone-like sulfamoyl diuretic. The closest structural analogues with direct human bioavailability data—metolazone, hydrochlorothiazide, and bumetanide—show high oral bioavailability, strongly supporting F >= 20%. The low azosemide result is less transferable and does not overcome the class-level evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for chlorthalidone itself is present in the evidence set.",
    "The available analogues vary in first-pass metabolism and solubility, so extrapolation is based on structural class rather than an exact match."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

